-- OAuth 2.1 clients, authorization codes, and opaque tokens for control-center-mcp.
-- Hashes only. No raw tokens, client secrets, or authorization codes.
-- Apply in the Lovable SQL editor. Do not edit this file to force it through.

begin;

create table if not exists public.cc_mcp_oauth_clients (
  client_id text primary key,
  client_secret_hash text,
  client_name text,
  actor_label text not null,
  redirect_uris text[] not null default '{}',
  grant_types text[] not null default array['authorization_code', 'refresh_token'],
  token_endpoint_auth_method text not null default 'none'
    check (token_endpoint_auth_method in ('none', 'client_secret_post')),
  created_at timestamptz not null default now(),
  check (actor_label ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
  check (client_secret_hash is null or token_endpoint_auth_method = 'client_secret_post')
);

create table if not exists public.cc_mcp_oauth_codes (
  code_hash text primary key,
  client_id text not null references public.cc_mcp_oauth_clients(client_id) on delete cascade,
  redirect_uri text not null,
  code_challenge text not null,
  code_challenge_method text not null default 'S256'
    check (code_challenge_method = 'S256'),
  scope text not null default 'control_center'
    check (scope = 'control_center'),
  resource text,
  authorized_by_user_id uuid,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create table if not exists public.cc_mcp_oauth_tokens (
  token_hash text primary key,
  refresh_token_hash text unique,
  client_id text not null references public.cc_mcp_oauth_clients(client_id) on delete cascade,
  scope text not null default 'control_center'
    check (scope = 'control_center'),
  actor_kind text not null default 'control_center_mcp'
    check (actor_kind = 'control_center_mcp'),
  actor_label text not null,
  resource text,
  authorized_by_user_id uuid,
  expires_at timestamptz not null,
  refresh_expires_at timestamptz not null default (now() + interval '30 days'),
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  check (actor_label ~ '^[a-z0-9][a-z0-9-]{0,63}$')
);

create index if not exists cc_mcp_oauth_tokens_client_idx
  on public.cc_mcp_oauth_tokens (client_id);

create index if not exists cc_mcp_oauth_tokens_refresh_exp_idx
  on public.cc_mcp_oauth_tokens (refresh_expires_at)
  where revoked_at is null;

create index if not exists cc_mcp_oauth_codes_expires_idx
  on public.cc_mcp_oauth_codes (expires_at);

alter table public.cc_mcp_oauth_clients enable row level security;
alter table public.cc_mcp_oauth_codes enable row level security;
alter table public.cc_mcp_oauth_tokens enable row level security;

revoke all on public.cc_mcp_oauth_clients from public, anon, authenticated;
revoke all on public.cc_mcp_oauth_codes from public, anon, authenticated;
revoke all on public.cc_mcp_oauth_tokens from public, anon, authenticated;

-- No authenticated or anon policies. The edge function uses service_role,
-- which bypasses RLS. A signed-in owner cannot read hashes from the browser.
drop policy if exists "Service role full access" on public.cc_mcp_oauth_clients;
drop policy if exists "Service role full access" on public.cc_mcp_oauth_codes;
drop policy if exists "Service role full access" on public.cc_mcp_oauth_tokens;

create policy "Service role full access" on public.cc_mcp_oauth_clients
  for all to service_role using (true) with check (true);
create policy "Service role full access" on public.cc_mcp_oauth_codes
  for all to service_role using (true) with check (true);
create policy "Service role full access" on public.cc_mcp_oauth_tokens
  for all to service_role using (true) with check (true);

comment on table public.cc_mcp_oauth_clients is
  'Dynamic OAuth clients for control-center-mcp. client_secret_hash is null for public PKCE clients.';
comment on table public.cc_mcp_oauth_codes is
  'One-time authorization codes stored as SHA-256 hashes. Raw codes are never stored.';
comment on table public.cc_mcp_oauth_tokens is
  'Opaque access and refresh tokens stored as SHA-256 hashes. actor_kind is always control_center_mcp.';

create or replace function public.cc_mcp_oauth_cleanup_expired()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  codes_deleted int := 0;
  tokens_deleted int := 0;
begin
  delete from public.cc_mcp_oauth_codes
   where expires_at < now();
  get diagnostics codes_deleted = row_count;

  delete from public.cc_mcp_oauth_tokens
   where (revoked_at is not null and revoked_at < now() - interval '7 days')
      or (expires_at < now() - interval '7 days' and refresh_expires_at < now());
  get diagnostics tokens_deleted = row_count;

  return jsonb_build_object(
    'ok', true,
    'codes_deleted', codes_deleted,
    'tokens_deleted', tokens_deleted
  );
end;
$$;

revoke all on function public.cc_mcp_oauth_cleanup_expired() from public, anon, authenticated;
grant execute on function public.cc_mcp_oauth_cleanup_expired() to service_role;

create or replace function public.cc_mcp_consume_oauth_code(
  p_code_hash text,
  p_client_id text,
  p_redirect_uri text,
  p_expected_challenge text,
  p_resource text,
  p_access_token_hash text,
  p_refresh_token_hash text,
  p_access_expires_at timestamptz,
  p_refresh_expires_at timestamptz
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_code public.cc_mcp_oauth_codes%rowtype;
  v_actor text;
  v_deleted int;
begin
  if p_code_hash is null or p_client_id is null or p_access_token_hash is null or p_refresh_token_hash is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'error', 'required fields missing');
  end if;

  select * into v_code
    from public.cc_mcp_oauth_codes
   where code_hash = p_code_hash
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'code not found or already used');
  end if;

  if v_code.expires_at < now() then
    delete from public.cc_mcp_oauth_codes where code_hash = p_code_hash;
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'code expired');
  end if;

  if v_code.client_id is distinct from p_client_id
     or v_code.redirect_uri is distinct from p_redirect_uri
     or v_code.code_challenge is distinct from p_expected_challenge then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'code, client, redirect, or pkce mismatch');
  end if;

  if v_code.resource is not null and p_resource is not null and v_code.resource is distinct from p_resource then
    return jsonb_build_object('ok', false, 'code', 'invalid_target', 'error', 'resource mismatch');
  end if;

  select actor_label into v_actor
    from public.cc_mcp_oauth_clients
   where client_id = p_client_id;

  if v_actor is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_client', 'error', 'unknown client');
  end if;

  delete from public.cc_mcp_oauth_codes where code_hash = p_code_hash;
  get diagnostics v_deleted = row_count;
  if v_deleted <> 1 then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'code already consumed');
  end if;

  insert into public.cc_mcp_oauth_tokens (
    token_hash, refresh_token_hash, client_id, scope, actor_kind, actor_label,
    resource, authorized_by_user_id, expires_at, refresh_expires_at
  ) values (
    p_access_token_hash, p_refresh_token_hash, p_client_id, 'control_center',
    'control_center_mcp', v_actor, coalesce(v_code.resource, p_resource),
    v_code.authorized_by_user_id, p_access_expires_at, p_refresh_expires_at
  );

  return jsonb_build_object(
    'ok', true,
    'scope', 'control_center',
    'actor_kind', 'control_center_mcp',
    'actor_label', v_actor
  );
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'token was not stored');
end;
$$;

revoke all on function public.cc_mcp_consume_oauth_code(
  text, text, text, text, text, text, text, timestamptz, timestamptz
) from public, anon, authenticated;
grant execute on function public.cc_mcp_consume_oauth_code(
  text, text, text, text, text, text, text, timestamptz, timestamptz
) to service_role;

create or replace function public.cc_mcp_rotate_oauth_refresh(
  p_refresh_token_hash text,
  p_client_id text,
  p_resource text,
  p_new_access_token_hash text,
  p_new_refresh_token_hash text,
  p_access_expires_at timestamptz
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tok public.cc_mcp_oauth_tokens%rowtype;
  v_updated int;
begin
  if p_refresh_token_hash is null or p_client_id is null
     or p_new_access_token_hash is null or p_new_refresh_token_hash is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'error', 'required fields missing');
  end if;

  select * into v_tok
    from public.cc_mcp_oauth_tokens
   where refresh_token_hash = p_refresh_token_hash
     and revoked_at is null
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'refresh not found or revoked');
  end if;

  if v_tok.client_id is distinct from p_client_id then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'client mismatch');
  end if;

  if p_resource is not null and v_tok.resource is not null and v_tok.resource is distinct from p_resource then
    return jsonb_build_object('ok', false, 'code', 'invalid_target', 'error', 'resource mismatch');
  end if;

  if v_tok.refresh_expires_at is null or v_tok.refresh_expires_at < now() then
    update public.cc_mcp_oauth_tokens
       set revoked_at = now()
     where token_hash = v_tok.token_hash;
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'refresh expired');
  end if;

  update public.cc_mcp_oauth_tokens
     set revoked_at = now()
   where token_hash = v_tok.token_hash
     and revoked_at is null;
  get diagnostics v_updated = row_count;
  if v_updated <> 1 then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'refresh already rotated');
  end if;

  insert into public.cc_mcp_oauth_tokens (
    token_hash, refresh_token_hash, client_id, scope, actor_kind, actor_label,
    resource, authorized_by_user_id, expires_at, refresh_expires_at
  ) values (
    p_new_access_token_hash, p_new_refresh_token_hash, p_client_id, v_tok.scope,
    'control_center_mcp', v_tok.actor_label, coalesce(v_tok.resource, p_resource),
    v_tok.authorized_by_user_id, p_access_expires_at, v_tok.refresh_expires_at
  );

  return jsonb_build_object(
    'ok', true,
    'actor_label', v_tok.actor_label,
    'refresh_expires_at', v_tok.refresh_expires_at,
    'scope', v_tok.scope
  );
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'code', 'invalid_grant', 'error', 'token was not stored');
end;
$$;

revoke all on function public.cc_mcp_rotate_oauth_refresh(
  text, text, text, text, text, timestamptz
) from public, anon, authenticated;
grant execute on function public.cc_mcp_rotate_oauth_refresh(
  text, text, text, text, text, timestamptz
) to service_role;

comment on function public.cc_mcp_consume_oauth_code is
  'Consume one authorization code and mint hashed tokens. Concurrent callers: exactly one success.';
comment on function public.cc_mcp_rotate_oauth_refresh is
  'Rotate one refresh-token family and keep its original refresh_expires_at.';

commit;
